INSERT INTO feature VALUES('indexed-sorts','descriptions','Dependent sorts in signatures','signatures-as-values','partial','notable',NULL,'Sorts indexed by other sorts, or by the host''s types, in a `theory` block and in `Model(S)`: a category with families, `Tm(g : Con, a : Ty(g))`, with its standard model in types and families and its sorts'' indices read back off its `Theory` value. The block''s category laws and laws on types check: their rules carry each context a substitution stands between, so two identities compose at one context, and the path order orients each rule with its written arguments before its indices (#5016). The identity law on terms reads and decides: a term substitution''s type index carries `subTy` with its two contexts, and the law''s two sorts agree modulo the identity law on types; a law whose sorts differ even modulo the laws at earlier sorts is refused `UndescribedMember.IllSorted` (#5042). `Model(S)` states an indexed sort as a function from its indices into the universe its classifier names, the computation types for a `Type[-]` sort, an index over the host''s types a binder at `Type` and one at a builtin type a binder at that type, a later field reading it applied and an applied index term passed in place, so a later index whose sort reads that call meets the same value, and an `include` of such a theory checks (#5051); a model''s member reads an earlier member applied, `type Tm(g : Con, a : Ty(g)) = (x : g) => a(x)`, a binder at a type family standing for a function being called where a type is read; a client reaches a model''s family through the model''s name, `Lists.T(Integer)` (#3051); a member answering a sort in the other ground sort is refused at its name. The composite law on terms, whose type index a law on types rewrites, is owed (#5117), a model''s law whose sides sort only modulo an earlier law, the identity law on terms among them (#5017), and ports at a computation sort (#2899).','surface-lowering theory-levitation theory-computads theory-path-orders kernel-term','corpus/model/higher-cells/cat-shape.gandr corpus/model/desc/lc/model-record.gandr corpus/model/desc/cwf.gandr corpus/model/desc/indexed-include.gandr corpus/pathological/desc/cwf.gandr corpus/pathological/desc/relative-monad.gandr corpus/ledger/diagnostics/UndescribedMember.IllSorted.gandr crates/kernel-term/src/theory_rules/tests.rs crates/theory-computads/src/indexing.rs','corpus/ledger/features/indexed-sorts.gandr','#5117 #5017 #2899');
